153	    private static final Map<Object, Site> sites = new IdentityHashMap<Object, Site>();
154	
155	    public static synchronized void reset() {
156	        sites.clear();
157	    }
158	
159	    private static final BigInteger INT_MIN = BigInteger.valueOf(Integer.MIN_VALUE);
160	    private static final BigInteger INT_MAX = BigInteger.valueOf(Integer.MAX_VALUE);
161	    private static final BigInteger LONG_MIN = BigInteger.valueOf(Long.MIN_VALUE);
162	    private static final BigInteger LONG_MAX = BigInteger.valueOf(Long.MAX_VALUE);
163	    private static final BigInteger NN32_MAX = BigInteger.ONE.shiftLeft(32).subtract(BigInteger.ONE);
164	    private static final BigInteger NN64_MAX = BigInteger.ONE.shiftLeft(64).subtract(BigInteger.ONE);
165	
166	    /** The digit part of a numeral's text, before its radix: digit-group separators and the radix point removed. */
167	    private static String digitPart(String text) {
168	        String s = text.replace("'", "").replace(" ", "");
169	        int under = s.indexOf('_');
170	        if (under >= 0) s = s.substring(0, under);
171	        return s.replace(".", "").replace("-", "");
172	    }
173	
174	    private static int radixOf(String text) {
175	        int under = text.indexOf('_');
176	        if (under < 0) return 10;
177	        try {
178	            return Integer.parseInt(text.substring(under + 1).trim());
179	        }
180	        catch (NumberFormatException ex) {
181	            return 10;
182	        }
183	    }
184	
185	    /** The value of the integer numeral x at its site. */
186	    public static FValue integer(IntLiteralExpr x) {
187	        synchronized (Numerals.class) {
188	            Site s = sites.get(x);
189	            if (s != null) return s.value;
190	            BigInteger v = x.getIntVal();
191	            s = new Site(NumeralNumbers.of(x), v);
192	            if (v.compareTo(INT_MIN) >= 0 && v.compareTo(INT_MAX) <= 0) {
193	                s.value = new IntNumeral(v.intValue(), s);
194	                s.plain = FInt.make(v.intValue());
195	            } else if (v.compareTo(LONG_MIN) >= 0 && v.compareTo(LONG_MAX) <= 0) {
196	                s.value = new LongNumeral(v.longValue(), s);
197	                s.plain = FLong.make(v.longValue());
198	            } else {
199	                s.value = new BigNumeral(v, s);
200	                s.plain = FBigNum.make(v);
201	            }
202	            sites.put(x, s);
203	            return s.value;
204	        }
205	    }
206	
207	    /** The value of the numeral with a radix point x at its site. */
208	    public static FValue radixPoint(FloatLiteralExpr x) {
209	        synchronized (Numerals.class) {
210	            Site s = sites.get(x);
211	            if (s != null) return s.value;
212	            NumeralNumbers nn = NumeralNumbers.of(x);
213	            BigInteger v = nn.v;
214	            int r = nn.r.intValue();
215	            int m = nn.m.intValue();
216	            // The exact value as the node holds it, a negated numeral's magnitude negated.
217	            BigInteger den = BigInteger.valueOf(x.getDenomBase()).pow(x.getDenomPower());
218	            BigInteger num = x.getIntPart().multiply(den).add(x.getNumerator());
219	            if (nn.kind == NumeralNumbers.Kind.NEGATED) num = num.abs().negate();
220	            s = new Site(nn, num);
221	            s.denomBase = x.getDenomBase();
222	            s.denomPower = x.getDenomPower();
223	            double d = simpleDoubleArith.numeralToDouble(v, r, m);
224	            if (nn.kind == NumeralNumbers.Kind.NEGATED) d = -d;   // -0.0 keeps its sign
225	            s.value = new FloatNumeral(d, s);
226	            s.plain = FFloat.make(d);
227	            sites.put(x, s);
228	            return s.value;
229	        }
230	    }
