242	    /** v is a numeral, or a tuple that holds one. */
243	    public static boolean hasNumeral(FValue v) {
244	        if (v instanceof Numeral) return true;
245	        if (v instanceof FTuple) for (FValue e : ((FTuple) v).getVals()) if (hasNumeral(e)) return true;
246	        return false;
247	    }
