249	    /** v without its numeral: a numeral's default alone, a tuple element by element. */
250	    public static FValue plain(FValue v) {
251	        if (v instanceof Numeral) return ((Numeral) v).site().plain;
252	        if (v instanceof FTuple) {
253	            if (!hasNumeral(v)) return v;
254	            return FTuple.make(plain(((FTuple) v).getVals()));
255	        }
256	        return v;
257	    }
