259	    public static List<FValue> plain(List<FValue> args) {
260	        boolean any = false;
261	        for (FValue v : args) if (hasNumeral(v)) any = true;
262	        if (!any) return args;
263	        List<FValue> l = new ArrayList<FValue>(args.size());
264	        for (FValue v : args) l.add(plain(v));
265	        return l;
266	    }
