268	    private static Environment library() {
269	        return Driver.getFortressLibrary();
270	    }
271	
272	    private static FType libraryType(String name) {
273	        try {
274	            return library().getRootTypeNull(name);
275	        }
276	        catch (RuntimeException ex) {
277	            return null;
278	        }
279	    }
