281	    /** NN32's type, which FortressBuiltin declares, so that FortressLibrary's root types do not hold it; or null. */
282	    private static FType nn32Type() {
283	        try {
284	            return FNN32.ZERO.type();
285	        }
286	        catch (RuntimeException ex) {
287	            return null;
288	        }
289	    }
290	
291	    /** The numeral's own type, NaturalNumeral or RadixPointNumeral, or null where the library has none. */
292	    public static FType numeralType(FValue v) {
293	        // The static numerals: a numeral's type exists only at compile time, so
294	        // no value has it when the program runs.
295	        return null;
296	    }
297	
298	    /** v is a numeral whose own type fits t as it is. */
299	    public static boolean fitsAsIs(FType t, FValue v) {
300	        FType nt = numeralType(v);
301	        return nt != null && !(t instanceof BottomType) && nt.subtypeOf(t);
302	    }
303	
304	    /**
305	     * Which of the float types the exact value of the site's numeral, as
306	     * written or folded, rounds to an infinity at: 0 none, 1 RR32 alone, 2
307	     * RR32 and RR64.
308	     */
309	    private static int infiniteAt(Site s) {
310	        // the answer is one for the site, so a read of it needs no lock
311	        int known = s.infiniteAt;
312	        if (known >= 0) return known;
313	        synchronized (s) {
314	            if (s.infiniteAt < 0) {
315	                BigInteger mag = s.signed.abs();
316	                // a magnitude below 2^127 rounds to a finite float
317	                if (mag.bitLength() <= 127) s.infiniteAt = 0;
318	                else if (!Float.isInfinite(simpleDoubleArith.numeralToFloat(mag, s.denomBase, s.denomPower))) s.infiniteAt = 0;
319	                else s.infiniteAt = Double.isInfinite(simpleDoubleArith.numeralToDouble(mag, s.denomBase, s.denomPower)) ? 2 : 1;
320	            }
321	            return s.infiniteAt;
322	        }
323	    }
324	
325	    /**
326	     * Whether v is a numeral with a radix point, as written or folded, t is
327	     * the library's RR64, the type of v's default, and v's exact value
328	     * rounds to an infinity there: at a place that fixes RR64 such a numeral
329	     * is refused as at any other type (literals.tex, "Literals"), though its
330	     * default is an RR64.  FType.typeMatch asks, so that the place looks for
331	     * a coercion, and inRange finds none.
332	     */
333	    public static boolean roundsToInfinityAsItIs(FType t, FValue v) {
334	        if (!(v instanceof FloatNumeral)) return false;
335	        if (t != v.type() && !(t.getName().equals("RR64") && t == libraryType("RR64"))) return false;
336	        return infiniteAt(((Numeral) v).site()) == 2;
337	    }
338	
339	    /** RR32's type, which FortressBuiltin declares, as NN32's; or null. */
340	    private static FType rr32Type() {
341	        try {
342	            return FRR32.ZERO.type();
343	        }
344	        catch (RuntimeException ex) {
345	            return null;
346	        }
347	    }
348	
349	    /**
350	     * Whether the numeral v is inside the range of target, where target is
351	     * one of the library's integer types, or rounds to a finite value there,
352	     * where target is the library's RR64 or RR32 (literals.tex, "Literals": a
353	     * numeral that rounds to an infinity is refused); true for every other
354	     * type.
355	     */
356	    static boolean inRange(FType target, FValue v) {
357	        Site s = ((Numeral) v).site();
358	        String n = target.getName();
359	        if (n.equals("RR64") || n.equals("RR32")) {
360	            if (target != (n.equals("RR32") ? rr32Type() : libraryType(n))) return true;
361	            return infiniteAt(s) < (n.equals("RR64") ? 2 : 1);
362	        }
363	        BigInteger lo, hi;
364	        if (n.equals("ZZ32")) { lo = INT_MIN; hi = INT_MAX; }
365	        else if (n.equals("ZZ64")) { lo = LONG_MIN; hi = LONG_MAX; }
366	        else if (n.equals("NN32")) { lo = BigInteger.ZERO; hi = NN32_MAX; }
367	        else if (n.equals("NN64")) { lo = BigInteger.ZERO; hi = NN64_MAX; }
368	        else return true;
369	        if (target != (n.equals("NN32") ? nn32Type() : libraryType(n))) return true;
370	        BigInteger value = s.radixPoint ? s.digitValue : s.signed;
371	        return value.compareTo(lo) >= 0 && value.compareTo(hi) <= 0;
372	    }
373	
374	    /** The numeral v converted to target by its coercion c, one value for its site at each type. */
375	    static FValue converted(FValue v, FType target, SingleFcn c) {
376	        Site s = ((Numeral) v).site();
377	        synchronized (s) {
378	            FValue r = s.converted.get(target);
379	            if (r == null) {
380	                r = convert(target, s, c);
381	                s.converted.put(target, r);
382	            }
383	            return r;
384	        }
385	    }
386	
387	    private static final java.util.Set<String> NUMBER_TYPES = new java.util.HashSet<String>(java.util.Arrays.asList(
388	        "ZZ32", "ZZ64", "NN32", "NN64", "ZZ", "QQ", "RR64", "RR32"));
389	
390	    /** Whether t is one of the library's eight number types, whose names no program may declare. */
391	    public static boolean isLibraryNumber(FType t) {
392	        return NUMBER_TYPES.contains(t.getName());
393	    }
394	
395	    /**
396	     * Whether target, a type that is not one of the library's number types,
397	     * declares a coercion from the type of the numeral v.  Its where clause
398	     * may take one numeral and refuse another of the same default, which the
399	     * dispatch caches' key does not tell apart.  A folded static expression
400	     * reaches such a type only as its default, so never by such a coercion.
401	     */
402	    static boolean ownCoercionFrom(FType target, FValue v) {
403	        if (!(v instanceof Numeral) || isStaticExpression(v) || isLibraryNumber(target)) return false;
404	        return !Coercions.numeralCoercions(target, ((Numeral) v).site().radixPoint).isEmpty();
405	    }
406	
407	    /** Whether v is the value of a folded static expression, not a numeral as written. */
408	    public static boolean isStaticExpression(FValue v) {
409	        return v instanceof Numeral && ((Numeral) v).site().kind == NumeralNumbers.Kind.STATIC;
410	    }
411	
412	    /**
413	     * The coercion to target that is generic over the numeral v's four
414	     * numbers, where its where clause holds at them; or null. For a negative
415	     * constant at a program's own type, also null where the type's prefix
416	     * minus does not apply to the coercion's result. The conversion runs here,
417	     * once for the site and the type, so that a refusal is known.
418	     */
419	    static SingleFcn numeralCoercion(FType target, FValue v) {
420	        Site s = ((Numeral) v).site();
421	        for (FGenericFunction g : Coercions.numeralCoercions(target, s.radixPoint)) {
422	            if (!whereHolds(g.getFnDecl(), numbers(g.getFnDecl(), s))) continue;
423	            synchronized (s) {
424	                if (!s.converted.containsKey(target)) {
425	                    FValue r = convert(target, s, g);
426	                    if (r == null) return null;
427	                    s.converted.put(target, r);
428	                }
429	            }
430	            return g;
431	        }
432	        return null;
433	    }
434	
435	    /**
436	     * The four numbers by the names the coercion's parameter type gives them:
437	     * NaturalNumeral[\n, r, v\] or RadixPointNumeral[\n, m, r, v\]. A numeral
438	     * has no sign: v is the numeral's digits read as one integer.
439	     */
440	    private static Map<String, BigInteger> numbers(FnDecl fd, Site s) {
441	        Map<String, BigInteger> m = new HashMap<String, BigInteger>();
442	        Type pt = (Type) fd.getHeader().getParams().get(0).getIdType().unwrap();
443	        List<StaticArg> args = ((TraitType) pt).getArgs();
444	        BigInteger last = s.digitValue;
445	        BigInteger[] ns = s.radixPoint
446	            ? new BigInteger[] { BigInteger.valueOf(s.digits), BigInteger.valueOf(s.fractionDigits), BigInteger.valueOf(s.radix), last }
447	            : new BigInteger[] { BigInteger.valueOf(s.digits), BigInteger.valueOf(s.radix), last };
448	        for (int i = 0; i < args.size() && i < ns.length; i++) {
449	            StaticArg a = args.get(i);
450	            if (a instanceof IntArg && ((IntArg) a).getIntVal() instanceof IntRef)
451	                m.put(((IntRef) ((IntArg) a).getIntVal()).getName().getText(), ns[i]);
452	        }
453	        return m;
454	    }
455	
456	    private static BigInteger evalSize(IntExpr e, Map<String, BigInteger> vals) {
457	        if (e instanceof IntBase) return ((IntBase) e).getIntVal().getIntVal();
458	        if (e instanceof IntRef) return vals.get(((IntRef) e).getName().getText());
459	        if (e instanceof IntBinaryOp) {
460	            IntBinaryOp b = (IntBinaryOp) e;
461	            BigInteger l = evalSize(b.getLeft(), vals), r = evalSize(b.getRight(), vals);
462	            if (l == null || r == null) return null;
463	            String op = b.getOp().getText();
464	            if (op.equals("+")) return l.add(r);
465	            if (op.equals("-")) return l.subtract(r);
466	            if (op.equals("^")) return l.pow(r.intValue());
467	            return l.multiply(r);
468	        }
469	        return null;
470	    }
471	
472	    /** Whether each comparison of sizes in the coercion's where clause holds at the four numbers. */
473	    private static boolean whereHolds(FnDecl fd, Map<String, BigInteger> vals) {
474	        Option<WhereClause> w = fd.getHeader().getWhereClause();
475	        if (w.isNone()) return true;
476	        for (WhereConstraint c : w.unwrap().getConstraints()) {
477	            if (!(c instanceof IntConstraint)) continue;
478	            IntConstraint ic = (IntConstraint) c;
479	            BigInteger l = evalSize(ic.getLeft(), vals), r = evalSize(ic.getRight(), vals);
480	            if (l == null || r == null) continue;
481	            int k = l.compareTo(r);
482	            String op = ic.getOp().getText();
483	            boolean ok = op.equals("<") ? k < 0 : op.equals("<=") ? k <= 0 : op.equals(">") ? k > 0
484	                       : op.equals(">=") ? k >= 0 : op.equals("=") ? k == 0 : true;
485	            if (!ok) return false;
486	        }
487	        return true;
488	    }
489	
490	    /**
491	     * The coercion's body, run once with the four numbers bound as exact
492	     * integers, ZZ values, and the coercion's type's own static parameters
493	     * bound to target's; its parameter is bound to no numeral value, since
494	     * none exists. For a negative constant at a program's own type, the
495	     * type's own prefix minus on the result; null where it does not apply.
496	     */
497	    private static FValue convert(FType target, Site s, SingleFcn c) {
498	        FGenericFunction g = (FGenericFunction) c;
499	        FnDecl fd = g.getFnDecl();
500	        boolean library = isLibraryNumber(target);
501	        // A folded constant at a library type, a negative constant among them,
502	        // converts from its exact value (P-173): only a numeral as written
503	        // reaches a numeral coercion. At a program's type a negative constant
504	        // is the type's own minus on the coercion of its magnitude (P-174).
505	        if (library && s.kind != NumeralNumbers.Kind.WRITTEN) return exactAt(target, s);
506	        boolean minusAfter = s.kind == NumeralNumbers.Kind.NEGATED;
507	        Map<String, BigInteger> vals = numbers(fd, s);
508	        Environment clenv = g.getEnv().extendAt(fd);
509	        List<StaticParam> sps = fd.getHeader().getStaticParams();
510	        if (target instanceof GenericTypeInstance) {
511	            List<FType> targs = ((GenericTypeInstance) target).getTypeParams();
512	            for (int i = 0; i < targs.size() && i < sps.size(); i++) clenv.putType(NodeUtil.getName(sps.get(i)), targs.get(i));
513	        }
514	        for (Map.Entry<String, BigInteger> e : vals.entrySet()) clenv.putValue(e.getKey(), FBigNum.make(e.getValue()));
515	        clenv.bless();
516	        Environment penv = clenv.extendAt(fd);
517	        penv.putValue(NodeUtil.nameString(fd.getHeader().getParams().get(0).getName()), FVoid.V);
518	        penv.bless();
519	        FValue r = new Evaluator(penv).eval(fd.getBody().unwrap());
520	        if (minusAfter) {
521	            Environment within = target.getWithin();
522	            // walk keys a prefix operator by its fixity (OprUtil.fixityDecorator)
