    private static BigInteger sizeValue(StaticArg a) {
        if (a instanceof IntArg && ((IntArg) a).getIntVal() instanceof IntBase)
            return ((IntBase) ((IntArg) a).getIntVal()).getIntVal().getIntVal();
        return null;
    }

